<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class Opportunity extends Model { protected $fillable=['tenant_id','pipeline_id','stage_id','contact_id','business_id','owner_id','name','value','currency_code','status','expected_close_at','closed_at','loss_reason','description','notes','next_activity_at','last_activity_at']; protected $casts=['value'=>'decimal:2','expected_close_at'=>'date','closed_at'=>'datetime','next_activity_at'=>'datetime','last_activity_at'=>'datetime']; public function pipeline(){return $this->belongsTo(SalesPipeline::class);} public function stage(){return $this->belongsTo(PipelineStage::class);} public function contact(){return $this->belongsTo(Contact::class);} public function company(){return $this->belongsTo(Business::class,'business_id');} public function owner(){return $this->belongsTo(User::class,'owner_id');} public function tasks(){return $this->hasMany(CrmTask::class);} public function appointments(){return $this->hasMany(Appointment::class);} public function activities(){return $this->hasMany(SalesActivity::class)->latest('occurred_at');} }
